/**
 * Baguio world geometry, generated from OpenStreetMap. Do not edit by hand.
 *
 * Regenerate with:
 *     python3 tools/extract_baguio_osm.py
 *     python3 tools/generate_baguio_ts.py
 *
 * OpenStreetMap contributors, ODbL 1.0. Retrieved 2026-10-06.
 * Bounding box: 120.5890,16.3980,120.6320,16.4280
 *
 * Coordinates are WGS84 degrees. `createProjector` in project.ts converts to
 * local metres, the same path landmarks use, so there is one projection and
 * not two that could disagree.
 *
 * Road polylines are real surveyed geometry. The hand-authored polylines this
 * replaced were invented to look plausible, and put roads through buildings.
 */

export interface RoadPath {
  /** OSM name, or '' when the way is unnamed. */
  name: string;
  /** Ordered [lat, lon] pairs in degrees. */
  points: readonly (readonly [number, number])[];
}

export interface RoadClassPaths {
  arterial: readonly RoadPath[];
  collector: readonly RoadPath[];
  local: readonly RoadPath[];
}

